#include <iostream>

// Overloaded functions performing different logic based on types
int square(int x) {
    return x * x;
}

double square(double y) {
    return y * y;
}

// Demonstrating distinct signatures with references
void modifyValue(int a, int& b) {
    b = a * 2;
}

int main() {
    int intVal = 7;
    double dblVal = 7.5;
    int result = 0;

    std::cout << "square(int): " << square(intVal) << "\n";
    std::cout << "square(double): " << square(dblVal) << "\n";

    modifyValue(intVal, result);
    std::cout << "modifyValue result: " << result << "\n";

    return 0;
}

#include <iostream>

// Function template maximum using C++11 trailing return type
template <typename T>
auto maximum(T value1, T value2, T value3) -> T {
    T maximumValue = value1;

    if (value2 > maximumValue) {
        maximumValue = value2;
    }

    if (value3 > maximumValue) {
        maximumValue = value3;
    }

    return maximumValue;
}

int main() {
    int i1 = 15, i2 = 42, i3 = 27;
    std::cout << "Max integer: " << maximum(i1, i2, i3) << "\n";

    double d1 = 3.14, d2 = 2.71, d3 = 9.81;
    std::cout << "Max double: " << maximum(d1, d2, d3) << "\n";

    char c1 = 'A', c2 = 'Z', c3 = 'M';
    std::cout << "Max character: " << maximum(c1, c2, c3) << "\n";

    return 0;
}

#include <iostream>

// Direct recursion: countdown
void countdown(int n) {
    if (n <= 0) { // Base case
        std::cout << "Liftoff!\n";
        return;
    }
    std::cout << n << " ";
    countdown(n - 1); // Recursive call (step)
}

// Forward declaration for indirect recursion
void functionB(int count);

void functionA(int count) {
    if (count > 0) {
        std::cout << "A:" << count << " ";
        functionB(count - 1); // Indirect recursive call
    }
}

void functionB(int count) {
    if (count > 0) {
        std::cout << "B:" << count << " ";
        functionA(count - 1); // Indirect recursive call
    }
}

int main() {
    std::cout << "Direct recursion: ";
    countdown(3);

    std::cout << "Indirect recursion: ";
    functionA(4);
    std::cout << "\n";

    return 0;
}
